public string Format(ReadOnlySpan<decimal> amounts)
{
    var buffer = ArrayPool<char>.Shared.Rent(amounts.Length * 24);
    try
    {
        var pos = 0;
        for (var i = 0; i < amounts.Length; i++)
        {
            if (i > 0) buffer[pos++] = ',';
            amounts[i].TryFormat(buffer.AsSpan(pos), out var written, "F2", CultureInfo.InvariantCulture);
            pos += written;
        }
        return new string(buffer, 0, pos);              // one final allocation
    }
    finally { ArrayPool<char>.Shared.Return(buffer); }
