// Contention: global lock held during I/O
private readonly object _gate = new();
public async Task<Rate> GetRateSlowAsync(string pair)
{
    lock (_gate)                                                       // blocks all callers
    {
        if (_cache.TryGetValue(pair, out var r)) return r;
        r = _client.GetRateAsync(pair).GetAwaiter().GetResult();       // I/O under lock + sync over async
        _cache[pair] = r; return r;
    }
}

// Fixed: lock-free reads, per-key async coalescing, no blocking
private readonly ConcurrentDictionary<string, Lazy<Task<Rate>>> _inflight = new();
public async Task<Rate> GetRateAsync(string pair, CancellationToken ct)
{
    if (_cache.TryGetValue(pair, out var cached) && !cached.IsExpired(_clock.GetUtcNow())) return cached;
    var lazy = _inflight.GetOrAdd(pair, p => new Lazy<Task<Rate>>(() => _client.GetRateAsync(p, CancellationToken.None)));
    try { var r = await lazy.Value.WaitAsync(ct); _cache[pair] = r; return r; }
    finally { _inflight.TryRemove(new KeyValuePair<string, Lazy<Task<Rate>>>(pair, lazy)); }
}
