// Deadline propagation: compute remaining budget and pass it on
app.Use(async (ctx, next) =>
{
    var deadline = ctx.Request.Headers.TryGetValue("X-Request-Deadline", out var d) && DateTimeOffset.TryParse(d, out var parsed)
        ? parsed : DateTimeOffset.UtcNow.AddMilliseconds(1200);              // default for edge requests
    ctx.Features.Set(new DeadlineFeature(deadline));
    using var cts = CancellationTokenSource.CreateLinkedTokenSource(ctx.RequestAborted);
    cts.CancelAfter(deadline - DateTimeOffset.UtcNow);
    ctx.RequestAborted = cts.Token;
    await next();
});

public async Task<FraudScore> ScoreAsync(Payment p, DeadlineFeature deadline, CancellationToken ct)
{
    var budget = TimeSpan.FromMilliseconds(Math.Min(500, (deadline.Value - DateTimeOffset.UtcNow).TotalMilliseconds - 300));  // leave 300ms for ledger
    if (budget <= TimeSpan.Zero) return FraudScore.RulesOnly(p);              // fallback: no budget left
    using var cts = CancellationTokenSource.CreateLinkedTokenSource(ct); cts.CancelAfter(budget);
    try { return await fraud.ScoreAsync(p, deadline.Value, cts.Token); }       // client sends X-Request-Deadline
    catch (OperationCanceledException) when (!ct.IsCancellationRequested) { return FraudScore.RulesOnly(p); }
}
