// Micro-batching writer: bounded channel, flush by size or time
public sealed class LedgerBatchWriter(IDbContextFactory<LedgerDb> dbs) : BackgroundService
{
    private readonly Channel<JournalEntry> _channel = Channel.CreateBounded<JournalEntry>(new BoundedChannelOptions(20_000)
        { FullMode = BoundedChannelFullMode.Wait });                       // backpressure

    public ValueTask EnqueueAsync(JournalEntry e, CancellationToken ct) => _channel.Writer.WriteAsync(e, ct);

    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        var batch = new List<JournalEntry>(500);
        while (await _channel.Reader.WaitToReadAsync(ct))
        {
            var deadline = DateTime.UtcNow.AddMilliseconds(10);
            while (batch.Count < 500 && DateTime.UtcNow < deadline && _channel.Reader.TryRead(out var e)) batch.Add(e);
            await using var db = await dbs.CreateDbContextAsync(ct);
            db.JournalEntries.AddRange(batch);                              // EF Core batches into few round trips
            await db.SaveChangesAsync(ct);
            batch.Clear();
        }
    }
}

