public static RiskTotals Compute(IReadOnlyList<Position> positions, MarketData md, int maxParallel)
{
    var totals = new RiskTotals();
    var gate = new object();
    Parallel.ForEach(
        Partitioner.Create(0, positions.Count, rangeSize: 2_000),                 // chunked ranges
        new ParallelOptions { MaxDegreeOfParallelism = maxParallel },
        () => new RiskTotals(),                                                   // local state per worker
        (range, _, local) =>
        {
            for (var i = range.Item1; i < range.Item2; i++) local.Add(RiskModel.Evaluate(positions[i], md));
