public static async IAsyncEnumerable<PaymentLine> ReadLinesAsync(Stream input, [EnumeratorCancellation] CancellationToken ct)
{
    var reader = PipeReader.Create(input, new StreamPipeReaderOptions(bufferSize: 256 * 1024));
    while (true)
    {
        var result = await reader.ReadAsync(ct);
        var buffer = result.Buffer;
        while (TryReadLine(ref buffer, out var line))
            if (PaymentLine.TryParse(line, out var parsed)) yield return parsed;     // span-based parsing, no per-line string
        reader.AdvanceTo(buffer.Start, buffer.End);                                 // tell the pipe what was consumed
        if (result.IsCompleted) break;
    }
    await reader.CompleteAsync();
}

static bool TryReadLine(ref ReadOnlySequence<byte> buffer, out ReadOnlySequence<byte> line)
{
    var pos = buffer.PositionOf((byte)'\n');
    if (pos is null) { line = default; return false; }
    line = buffer.Slice(0, pos.Value);
    buffer = buffer.Slice(buffer.GetPosition(1, pos.Value));
    return true;
}
