// Hot-row relief: append-only ledger entries + periodic snapshot instead of updating one balance row per payment
public async Task PostAsync(Guid accountId, decimal amount, Guid paymentId, CancellationToken ct)
{
    db.LedgerEntries.Add(new LedgerEntry(accountId, amount, paymentId, clock.UtcNow));   // insert-only: no row lock contention
    await db.SaveChangesAsync(ct);
}

public async Task<decimal> BalanceAsync(Guid accountId, CancellationToken ct)
{
    var snap = await db.BalanceSnapshots.Where(s => s.AccountId == accountId).OrderByDescending(s => s.AsOf).FirstOrDefaultAsync(ct);
    var since = snap?.AsOf ?? DateTimeOffset.MinValue;
    var delta = await db.LedgerEntries.Where(e => e.AccountId == accountId && e.PostedAt > since).SumAsync(e => e.Amount, ct);
    return (snap?.Balance ?? 0m) + delta;                                               // snapshot job compacts every few minutes
}
// Shard key for cells: hash(merchantId) -> cell; very large merchants get dedicated cells
