// Allocation-free hot path: preallocated state, struct commands, single owner thread per partition
public readonly record struct OrderCheck(long AccountId, int InstrumentId, long Quantity, long PriceTicks, long CorrelationId);

public sealed class RiskPartition
{
    private readonly long[] _positionByInstrument;         // preallocated per partition
    private readonly long[] _limitByInstrument;
    private long _notionalUsed, _notionalLimit;

    public RiskPartition(int instruments, long notionalLimit)
    {
        _positionByInstrument = new long[instruments];
        _limitByInstrument = new long[instruments];
        _notionalLimit = notionalLimit;
    }

    // Called only by the partition's owner thread: no locks, no allocations
    public bool Check(in OrderCheck o)
    {
        var newPos = _positionByInstrument[o.InstrumentId] + o.Quantity;
        if (Math.Abs(newPos) > _limitByInstrument[o.InstrumentId]) return false;
        var notional = o.Quantity * o.PriceTicks;
        if (_notionalUsed + Math.Abs(notional) > _notionalLimit) return false;
        _positionByInstrument[o.InstrumentId] = newPos;
        _notionalUsed += Math.Abs(notional);
        return true;
    }
}
// Ingress: lock-free ring buffer per partition; owner thread pinned to an isolated core; journal written by another thread
