// Per-stage latency from headers: produced-at (stage start) and original initiation time (end to end)
static readonly Histogram<double> StageQueue = new Meter("Bank.Pipeline").CreateHistogram<double>("pipeline.stage.queue_latency", "s");
static readonly Histogram<double> EndToEnd = new Meter("Bank.Pipeline").CreateHistogram<double>("pipeline.end_to_end_latency", "s");

public async Task HandleAsync(ConsumeResult<string, byte[]> msg, CancellationToken ct)
{
    var producedAt = Header.Time(msg, "produced-at");
    var initiatedAt = Header.Time(msg, "payment-initiated-at");
    StageQueue.Record((DateTimeOffset.UtcNow - producedAt).TotalSeconds, new KeyValuePair<string, object?>("stage", "ledger"));

    await ledger.PostAsync(Deserialize(msg), ct);

    EndToEnd.Record((DateTimeOffset.UtcNow - initiatedAt).TotalSeconds, new KeyValuePair<string, object?>("milestone", "posted"));
}
